//! Algorithm argument access projected from the registered consumption declaration.
/// Restrict an admitted input to the exact generated argument fields.
/// Multiplicity and zero-column row counts survive the Arrow projection.
/// # Errors
/// Unknown argument, differing declaration, or native projection failure.
pub fn project(
    algorithm: pse_ids::SemanticId,
    port: &str,
    input: &crate::columnar::FieldCheckedBatch,
    registry: &pse_schema::Registry,
) -> Result<arrow::record_batch::RecordBatch, crate::RelationError> {
    let argument = registry
        .algorithms()
        .iter()
        .find(|spec| spec.id == algorithm)
        .and_then(|spec| spec.inputs.iter().find(|input| input.port == port))
        .ok_or_else(|| crate::RelationError::UnknownRegistry {
            relation: format!("algorithm argument {algorithm}:{port}"),
        })?;
    let relation = registry
        .relation(&argument.relation)
        .ok_or_else(|| crate::RelationError::UnknownRegistry {
            relation: argument.relation.clone(),
        })?;
    input.check_declaration(registry, relation)?;
    let indices = relation
        .columns
        .iter()
        .enumerate()
        .filter_map(|(index, field)| {
            match &argument.consumption {
                pse_schema::model::algorithm::InputConsumption::Whole => Some(index),
                pse_schema::model::algorithm::InputConsumption::Columns(columns) => {
                    columns.contains(field.name()).then_some(index)
                }
            }
        })
        .collect::<Vec<_>>();
    let projected = input.batch().project(&indices)?;
    let schema = std::sync::Arc::new(
        arrow::datatypes::Schema::new(projected.schema().fields().clone()),
    );
    Ok(
        arrow::record_batch::RecordBatch::try_new_with_options(
            schema,
            projected.columns().to_vec(),
            &arrow::record_batch::RecordBatchOptions::new()
                .with_row_count(Some(projected.num_rows())),
        )?,
    )
}
